<div class="patient-page-heading"><div><span class="eyebrow text-secondary">DIRECTORIO DE ATENCIÓN</span><h1>Pacientes</h1><p class="text-secondary mb-0">Consulta y administra los datos de nuestros pacientes.</p></div><a class="btn btn-clinic" href="/pacientes/nuevo">+ Registrar paciente</a></div>
<section class="patient-card" aria-label="Listado de pacientes" data-patient-total="<?= $escape($result['total']) ?>">
<div class="patient-list-toolbar"><div><strong><?= $escape($result['total']) ?></strong> <?= $search!=='' ? 'resultados encontrados' : 'pacientes registrados' ?><span class="live-label">Datos de PostgreSQL</span></div>
<form action="/pacientes" method="get" class="patient-search" role="search"><label for="q" class="visually-hidden">Buscar por nombre, apellido o documento</label><input type="search" class="form-control" id="q" name="q" maxlength="200" value="<?= $escape($search) ?>" placeholder="Nombre, apellido o documento"><button class="btn btn-clinic" type="submit">Buscar</button><?php if($search!==''): ?><a class="btn btn-outline-secondary" href="/pacientes">Limpiar</a><?php endif; ?></form></div>
<?php if(!$result['items']): ?><div class="patient-empty"><span aria-hidden="true">⌕</span><h2 class="h5">No hay pacientes para mostrar</h2><p class="text-secondary"><?= $search!=='' ? 'Prueba con otro nombre, apellido o documento.' : 'Los nuevos pacientes aparecerán aquí cuando se registren.' ?></p><a href="/pacientes">Ver todos los pacientes</a></div>
<?php else: ?><div class="table-responsive"><table class="table patient-table align-middle mb-0"><caption class="visually-hidden">Pacientes: código, nombre, documento, estado y acciones</caption><thead><tr><th scope="col">Paciente</th><th scope="col">Código</th><th scope="col">Documento</th><th scope="col">Estado</th><th scope="col" class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach($result['items'] as $patient): ?><tr><td><div class="patient-name"><span class="patient-avatar" aria-hidden="true"><?= $escape(mb_substr($patient['nombres'],0,1).mb_substr($patient['apellidos'],0,1)) ?></span><strong><?= $escape($patient['apellidos'].', '.$patient['nombres']) ?></strong></div></td><td><?= $escape($patient['codigo_paciente']) ?></td><td><?= $escape($patient['documento_identidad']) ?></td><td><span class="status-chip <?= $patient['estado']==='activo' ? 'is-active' : 'is-inactive' ?>"><?= $escape(ucfirst($patient['estado'])) ?></span></td><td><div class="patient-row-actions"><a href="/pacientes/detalle?id=<?= $escape($patient['id_paciente']) ?>" aria-label="Ver detalle de <?= $escape($patient['nombres'].' '.$patient['apellidos']) ?>">Ver detalle</a><a href="/pacientes/editar?id=<?= $escape($patient['id_paciente']) ?>" aria-label="Editar a <?= $escape($patient['nombres'].' '.$patient['apellidos']) ?>">Editar</a></div></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
<div class="patient-pagination"><span><?= $result['total'] ? 'Mostrando '.(($result['page']-1)*10+1).'–'.min($result['total'],$result['page']*10).' de '.$result['total'] : '0 resultados' ?></span><nav aria-label="Páginas de pacientes"><ul class="pagination mb-0">
<?php $pageUrl=static fn(int $page): string=>'/pacientes?'.http_build_query(['q'=>$search,'pagina'=>$page]); ?>
<?php if($result['page']>1): ?><li class="page-item"><a class="page-link" href="<?= $escape($pageUrl($result['page']-1)) ?>">Anterior</a></li><?php endif; ?>
<?php for($p=max(1,$result['page']-2);$p<=min($result['pages'],$result['page']+2);$p++): ?><li class="page-item <?= $p===$result['page'] ? 'active' : '' ?>"><a class="page-link" <?= $p===$result['page'] ? 'aria-current="page"' : '' ?> href="<?= $escape($pageUrl($p)) ?>"><?= $p ?></a></li><?php endfor; ?>
<?php if($result['page']<$result['pages']): ?><li class="page-item"><a class="page-link" href="<?= $escape($pageUrl($result['page']+1)) ?>">Siguiente</a></li><?php endif; ?></ul></nav></div>
</section>
